SELECT SUM(CASE WHEN p.gender = 1 THEN 1 ELSE 0 END) AS male_count, SUM(CASE WHEN p.gender = 2 THEN 1 ELSE 0 END) AS female_count, ROUND(SUM(CASE WHEN p.gender = 1 THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN p.gender = 2 THEN 1 ELSE 0 END), 0), 2) AS male_female_ratio FROM ads_person_basic_info p INNER JOIN ads_residence_relation rr ON p.person_id = rr.person_id AND rr.delete_flag = 0 INNER JOIN ads_house_basic_info h ON rr.house_id = h.house_id AND h.delete_flag = 0 WHERE p.delete_flag = 0 AND h.dept_id = 310105004005;
